{
  "pairs": {
    "conflict_85fb8b275787df277606b3c3": {
      "classification": "different_products_origins_or_programs",
      "reason": "Claim 1 (HRL H155115) finds substantial transformation for a specific TCE vehicle assembly involving U.S. origin parts and foreign components, whereas Claim 2 cites HQ 563045 and HQ 734393 stating that assembling battery cells into packs does not constitute substantial transformation because the fundamental character is unaltered. These address different processing scopes (full vehicle vs. cell-to-pack assembly) and distinct historical rulings.",
      "verification_question": "Does the specific TCE vehicle assembly in HRL H155115 involve additional U.S. manufacturing steps beyond battery pack assembly that distinguish it from the simple cell-to-pack processes described in HQ 563045?"
    },
    "conflict_fc58b65443e223bc3a88ea2f": {
      "classification": "different_dates_or_policy_stages",
      "reason": "Claim 1 states Hyundai will not pay tariffs at the grand opening of Metaplant, while Claim 2 notes that Hyundai paid billions in levies after a 25% tariff was placed in spring 2025, with plans to lower rates to 15%. The statements reflect different policy stages: an existing high tariff regime versus a subsequent reduction or specific exemption context.",
      "verification_question": "Does the 'no tariffs' statement for Hyundai's Metaplant opening refer to a specific exemption, USMCA qualification, or a future effective date distinct from the 25% spring 2025 levy period?"
    },
    "conflict_c4e9f22da1e514ef87a3b7c7": {
      "classification": "different_products_origins_or_programs",
      "reason": "Claim 1 specifies Section 232 tariffs on steel, aluminum, and copper at 50 percent for gear manufacturers. Claim 2 references a 25% tariff on EV models grounded in national security concerns under the Trade Expansion Act. These refer to different duty rates (50% vs 25%) and potentially different product scopes (raw materials/derivative products vs. finished vehicles).",
      "verification_question": "Are the 50% Section 232 tariffs on steel/aluminum/copper distinct from the 25% tariff applied to specific EV models, or do they apply cumulatively to the same imported goods?"
    },
    "conflict_3b106938e6160c5b4969e8b8": {
      "classification": "different_dates_or_policy_stages",
      "reason": "Claim 1 states a 25% tariff on auto parts took effect May 3, 2025. Claim 2 asserts the real number for covered parts is 27.5% or higher in 2026. This indicates a policy change or additional surcharge occurring after the initial 2025 effective date.",
      "verification_question": "What specific policy change, surcharge, or additional duty component enacted between May 2025 and 2026 increased the auto parts tariff from 25% to 27.5% or higher?"
    },
    "conflict_a8357553daa3f505428975cd": {
      "classification": "complementary_or_no_conflict",
      "reason": "Claim 1 states the antidumping investigation for Vietnam is terminated due to negligibility. Claim 2 states Commerce will continue investigations for Korea, Taiwan, Thailand, and Vietnam. The texts are consistent: investigations continue for most countries, but the specific antidumping component for Vietnam is terminated while countervailing duties may proceed, or the termination applies only to the AD portion as explicitly stated in the full context.",
      "verification_question": "Does the termination of the antidumping investigation for Vietnam preclude the continuation of the countervailing duty investigation mentioned in the same USITC determination?"
    }
  }
}
